const icons={home:'⌂',calendar:'▦',orders:'▣',listings:'☰',earnings:'₱',profile:'◯',search:'⌕',arrow:'→',plus:'+'};
const navIconNames={home:'home-01',calendar:'calendar-03',orders:'package-delivered',listings:'grid-02',earnings:'wallet-01',menu:'menu-01',profile:'user-circle'};
const navIcon=(icon,active)=>`<i class="nav-hugeicon ${active?'hgi-solid ':''}hgi-stroke hgi-${navIconNames[icon]||icon}${active?' nav-hugeicon-active':''}" aria-hidden="true"></i>`;
const esc=s=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const state={page:'dashboard',role:'Owner',ordersPaused:false,orderFilter:'All',orderTypeFilter:'All',orderStatusFilter:'All',orderPaymentFilter:'All',query:'',orderView:'list',range:'Today',detail:null,listing:null,toast:'',dashboardScroll:0,insightQuery:'',insightSort:'count',insightMetric:'revenue',insightTab:'listings',performanceTab:'top',filterSheet:false,filterDraftRange:'Today',compareMode:'previous',filterDraftCompare:'previous',customFrom:'',customTo:'',devPosition:null,listingsExportOpen:false,insightsDownloadOpen:false,listingsZeroOnly:false,listingSortOpen:false};
