function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.detail=null;render()});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{state.detail=b.dataset.detail;render()});document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{state.range=b.dataset.range;render()});document.querySelectorAll('[data-order-filter]').forEach(b=>b.onclick=()=>{state.orderFilter=b.dataset.orderFilter;render()});document.querySelectorAll('[data-order-type]').forEach(b=>b.onclick=()=>{state.orderTypeFilter=b.dataset.orderType;render()});document.querySelectorAll('[data-order-status]').forEach(b=>b.onclick=()=>{state.orderStatusFilter=b.dataset.orderStatus;render()});document.querySelectorAll('[data-order-payment]').forEach(b=>b.onclick=()=>{state.orderPaymentFilter=b.dataset.orderPayment;render()});document.querySelectorAll('[data-order-filter-link]').forEach(b=>b.onclick=()=>{state.page='orders';state.orderFilter=b.dataset.orderFilterLink;state.orderStatusFilter=b.dataset.orderFilterLink;render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.orderView=b.dataset.view;render()});document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{state.role=b.dataset.role;render()});const dateToggle=document.querySelector('[data-date-toggle]');if(dateToggle)dateToggle.onclick=()=>dateToggle.parentElement.classList.toggle('open');const toggle=document.querySelector('[data-toggle-orders]');if(toggle)toggle.onclick=()=>{state.ordersPaused=!state.ordersPaused;toast(state.ordersPaused?'Orders paused':'Orders accepting');render()};const trigger=document.querySelector('.dev-tools-trigger');if(trigger){const dev=document.querySelector('.dev-tools');let dragging=false,moved=false,startX=0,startY=0,startLeft=0,startTop=0,frame,frameRect;trigger.onclick=()=>{if(moved){moved=false;return}dev.classList.toggle('open')};trigger.onpointerdown=e=>{dragging=true;moved=false;startX=e.clientX;startY=e.clientY;const rect=dev.getBoundingClientRect();startLeft=rect.left;startTop=rect.top;frame=dev.offsetParent||document.documentElement;frameRect=frame.getBoundingClientRect();dev.classList.remove('open');trigger.setPointerCapture?.(e.pointerId)};trigger.onpointermove=e=>{if(!dragging)return;const dx=e.clientX-startX,dy=e.clientY-startY;if(Math.abs(dx)>3||Math.abs(dy)>3)moved=true;if(!moved)return;const left=Math.max(8,Math.min(frame.clientWidth-dev.offsetWidth-8,startLeft+dx-frameRect.left)),top=Math.max(8,Math.min(frame.clientHeight-dev.offsetHeight-8,startTop+dy-frameRect.top));state.devPosition={left,top};dev.style.left=left+'px';dev.style.top=top+'px';dev.style.right='auto';dev.style.bottom='auto';e.preventDefault()};const stop=e=>{if(!dragging)return;dragging=false;trigger.releasePointerCapture?.(e.pointerId)};trigger.onpointerup=stop;trigger.onpointercancel=stop}const search=document.querySelector('[data-search]');if(search){search.oninput=e=>{state.query=e.target.value;const pos=e.target.selectionStart;render();const next=document.querySelector('[data-search]');next.focus();next.setSelectionRange(pos,pos)}}document.querySelectorAll('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));document.querySelectorAll('[data-logout]').forEach(b=>b.onclick=()=>{if(window.confirm('Log out of Cabana Vendor Portal?'))toast('Logged out')});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const o=orders.find(x=>x.id===state.detail);const a=b.dataset.action;if(a==='confirm')o.status='Confirmed';if(a==='preparing')o.status='Preparing';if(a==='ready')o.status='Ready';if(a==='complete')o.status='Completed';if(a==='cancel'){o.status='Cancelled';toast('Cancellation recorded')}if(a==='reschedule')toast('Reschedule request opened');if(a!=='reschedule')toast(`Order ${o.id} updated`);render()});document.querySelectorAll('[data-listing-new]').forEach(b=>b.onclick=()=>toast('New listing form opened'))}
